1	/* Alunix K1 Skymning — runda 4. Hela signaturen (fönsterresa, ram, utgång)
2	   är EN pinnad akt (#signature); allt annat om fönstermasken/utgången är
3	   bespoke, driven av assets/push/window-track.json och --sc-p. Motorn
4	   (scrollcraft.js) rörs aldrig här; #signature använder ingen
5	   data-sc-sequence -- bildsekvensen laddas och ritas helt själv (se
6	   loadFrames/applySignature), så kartläggningen ruta<->p är vår, inte
7	   motorns dwell/scrub-formel. */
8	(function () {
9	  'use strict';
10	
11	  var NATURAL_W = 1440, NATURAL_H = 960;
12	  var FRAME_COUNT = 100;
13	  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
14	
15	  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
16	  function smooth(x) { x = clamp01(x); return x * x * (3 - 2 * x); }
17	
18	  function coverBox(boxW, boxH, natW, natH) {
19	    var scale = Math.max(boxW / natW, boxH / natH);
20	    var drawnW = natW * scale, drawnH = natH * scale;
21	    return { scale: scale, offX: (boxW - drawnW) / 2, offY: (boxH - drawnH) / 2 };
22	  }
23	
24	  function frameBox(kf, boxW, boxH) {
25	    var c = coverBox(boxW, boxH, NATURAL_W, NATURAL_H);
26	    var px = c.offX + kf.x * NATURAL_W * c.scale;
27	    var py = c.offY + kf.y * NATURAL_H * c.scale;
28	    var pw = kf.w * NATURAL_W * c.scale;
29	    var ph = kf.h * NATURAL_H * c.scale;
30	    return { px: px, py: py, pw: pw, ph: ph, archH: kf.arch * ph };
31	  }
32	
33	  function pathFor(box) {
34	    var pw = box.pw, ph = box.ph, a = box.archH;
35	    return 'path("M0,' + a.toFixed(1) + ' L0,' + ph.toFixed(1) + ' L' + pw.toFixed(1) + ',' + ph.toFixed(1) +
36	      ' L' + pw.toFixed(1) + ',' + a.toFixed(1) + ' A' + (pw / 2).toFixed(1) + ',' + a.toFixed(1) +
37	      ' 0 0 0 0,' + a.toFixed(1) + ' Z")';
38	  }
39	
40	  function interpTrack(frame, keys) {
41	    if (frame <= keys[0].frame) return keys[0];
42	    if (frame >= keys[keys.length - 1].frame) return keys[keys.length - 1];
43	    for (var i = 0; i < keys.length - 1; i++) {
44	      var a = keys[i], b = keys[i + 1];
45	      if (frame >= a.frame && frame <= b.frame) {
46	        var t = (frame - a.frame) / (b.frame - a.frame);
47	        return {
48	          x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t,
49	          w: a.w + (b.w - a.w) * t, h: a.h + (b.h - a.h) * t,
50	          arch: a.arch + (b.arch - a.arch) * t
51	        };
52	      }
53	    }
54	    return keys[keys.length - 1];
55	  }
56	
57	  function makeHoraiFrame(cls, title) {
58	    var f = document.createElement('iframe');
59	    f.className = cls;
60	    f.title = title;
61	    f.loading = 'eager';
62	    f.src = '/sites/horai.html';
63	    return f;
64	  }
65	
66	  // Egen preload av de 100 rutorna (runda 4: aldrig motorns
67	  // data-sc-sequence/data-sc-scrub -- se filhuvudet).
68	  function loadFrames() {
69	    var frames = [], loaded = 0;
70	    for (var i = 0; i < FRAME_COUNT; i++) {
71	      (function (i) {
72	        var img = new Image();
73	        img.decoding = 'async';
74	        img.src = 'assets/push/f' + String(i + 1).padStart(3, '0') + '.webp';
75	        img.onload = function () { loaded++; };
76	        frames[i] = img;
77	      })(i);
78	    }
79	    return { frames: frames, get loaded() { return loaded; }, count: FRAME_COUNT };
80	  }
81	
82	  // ---- reduced motion: render the one static formed frame, mount nothing ----
83	  function renderStatic(track) {
84	    var stage = document.getElementById('rm-window-stage');
85	    var photo = document.getElementById('rm-window-photo');
86	    var mask = document.getElementById('rm-window-mask');
87	    if (stage && photo && mask) {
88	      var apply = function () {
89	        var box = frameBox(track.keys[track.keys.length - 1], stage.clientWidth, stage.clientHeight);
90	        mask.style.left = box.px + 'px'; mask.style.top = box.py + 'px';
91	        mask.style.width = box.pw + 'px'; mask.style.height = box.ph + 'px';
92	        mask.style.clipPath = pathFor(box);
93	      };
94	      if (photo.complete) apply(); else photo.addEventListener('load', apply, { once: true });
95	      addEventListener('resize', apply, { passive: true });
96	    }
97	    var slot = document.getElementById('rm-frame-slot');
98	    if (slot) slot.appendChild(makeHoraiFrame('rm-frame', 'Hōrai, exempelsajt'));
99	  }
100	
101	  // ---- motion build ----
102	  function startMotion(track) {
103	    document.documentElement.classList.add('motion');
104	    var api = ScrollCraft.mount(document.body);
105	
106	    var sigAct = null, ledgerAct = null;
107	    for (var i = 0; i < api.acts.length; i++) {
108	      var id = api.acts[i].el.id;
109	      if (id === 'signature') sigAct = api.acts[i];
110	      if (id === 'ledger') ledgerAct = api.acts[i];
111	    }
112	    if (!sigAct) return;
113	
114	    var seq = loadFrames();
115	
116	    var canvas = document.querySelector('.sig-canvas');
117	    var cctx = canvas && canvas.getContext('2d', { alpha: false });
118	    var photoLayer = document.getElementById('sig-photo-layer');
119	    var glow = document.querySelector('.window-glow');
120	    var fill = document.querySelector('.window-fill');
121	    var glassWrap = document.querySelector('.window-glass');
122	    var glassCanvas = document.querySelector('.window-glass__canvas');
123	    var gctx = glassCanvas && glassCanvas.getContext('2d');
124	    var topbarLabel = document.getElementById('topbar-label');
125	    var topbar = document.getElementById('topbar');
126	    var lastDrawnIdx = -1;
127	    var originSet = false;
128	
129	    // Ramen skapas i JS, aldrig med src i statisk HTML: annars laddar den
130	    // även när #signature aldrig blir aktiv (två-iframes-felet, runda 3).
131	    var revealFrame = makeHoraiFrame('', 'Hōrai, exempelsajt');
132	    revealFrame.style.visibility = 'hidden';
133	    var frameSlot = document.getElementById('reveal-frame-slot');
134	    if (frameSlot) frameSlot.appendChild(revealFrame);
135	
136	    function resizeCanvas() {
137	      if (!canvas) return;
138	      var box = canvas.getBoundingClientRect();
139	      var dpr = Math.min(devicePixelRatio || 1, 2);
140	      canvas.width = Math.round(box.width * dpr);
141	      canvas.height = Math.round(box.height * dpr);
142	      lastDrawnIdx = -1;
143	      originSet = false;
144	    }
145	    resizeCanvas();
146	    addEventListener('resize', resizeCanvas, { passive: true });
147	
148	    function drawFrame(idx) {
149	      var img = seq.frames[idx];
150	      if (!img || !img.complete || !img.naturalWidth || !cctx) return false;
151	      var cw = canvas.width, ch = canvas.height;
152	      var scale = Math.max(cw / img.naturalWidth, ch / img.naturalHeight);
153	      var w = img.naturalWidth * scale, h = img.naturalHeight * scale;
154	      cctx.drawImage(img, (cw - w) / 2, (ch - h) / 2, w, h);
155	      return true;
156	    }
157	
158	    function applySignature() {
159	      var p = sigAct.p;
160	      var stage = sigAct.stage;
161	      if (!stage) return;
162	
163	      // ---- fas 1 (p 0-0.46): kameraresan, ritad själv ----
164	      var t1 = clamp01(p / 0.46);
165	      var idx = Math.min(FRAME_COUNT - 1, Math.max(0, Math.round(t1 * (FRAME_COUNT - 1))));
166	      var frame = idx + 1;
167	      // Bugg (runda 5): lastDrawnIdx sattes tidigare även när ritningen tyst
168	      // gav upp (bilden inte klar än via nätverket) -- vid p=0, direkt efter
169	      // sidladdning, hann f001.webp nästan aldrig ligga klar till första
170	      // rAF-anropet, så canvasen fastnade svart för alltid eftersom idx
171	      // aldrig ändrades igen utan scroll. Försöker nu om varje ruta tills
172	      // ritningen faktiskt lyckas.
173	      if (idx !== lastDrawnIdx) { if (drawFrame(idx)) lastDrawnIdx = idx; }
174	
175	      var boxW = stage.clientWidth, boxH = stage.clientHeight;
176	      if (frame < 58) {
177	        glow.style.opacity = 0; fill.style.opacity = 0; glassWrap.style.opacity = 0;
178	      } else {
179	        var kf = interpTrack(frame, track.keys);
180	        var box = frameBox(kf, boxW, boxH);
181	        var path = pathFor(box);
182	        [glow, fill, glassWrap].forEach(function (el) {
183	          el.style.left = box.px + 'px'; el.style.top = box.py + 'px';
184	          el.style.width = box.pw + 'px'; el.style.height = box.ph + 'px';
185	          el.style.clipPath = path;
186	        });
187	        var fillT = smooth((frame - track.first_frame_with_horai) / 6);
188	        fill.style.opacity = fillT.toFixed(3);
189	        glassWrap.style.opacity = (0.15 + fillT * 0.4).toFixed(3);
190	        glow.style.opacity = (1 - fillT * 0.8).toFixed(3);
191	
192	        if (frame >= track.first_frame_with_horai) {
193	          var sx = kf.x * NATURAL_W, sy = kf.y * NATURAL_H, sw = kf.w * NATURAL_W, sh = kf.h * NATURAL_H;
194	          var dpr = Math.min(devicePixelRatio || 1, 2);
195	          glassCanvas.width = Math.max(1, Math.round(box.pw * dpr));
196	          glassCanvas.height = Math.max(1, Math.round(box.ph * dpr));
197	          gctx.setTransform(dpr, 0, 0, dpr, 0, 0);
198	          var img100 = seq.frames[FRAME_COUNT - 1];
199	          var srcImg = seq.frames[idx] && seq.frames[idx].complete ? seq.frames[idx] : img100;
200	          if (srcImg && srcImg.complete) gctx.drawImage(srcImg, sx, sy, sw, sh, 0, 0, box.pw, box.ph);
201	        }
202	
203	        // Transform-ursprung för fas "fortsatt zoom" (p 0.46-0.50): satt en
204	        // gång, mot fönstrets mittpunkt vid sista rutan.
205	        if (!originSet && frame === FRAME_COUNT) {
206	          var lastBox = frameBox(track.keys[track.keys.length - 1], boxW, boxH);
207	          var ox = ((lastBox.px + lastBox.pw / 2) / boxW * 100).toFixed(2) + '%';
208	          var oy = ((lastBox.py + lastBox.ph / 2) / boxH * 100).toFixed(2) + '%';
209	          photoLayer.style.setProperty('--sig-window-x', ox);
210	          photoLayer.style.setProperty('--sig-window-y', oy);
211	          originSet = true;
212	        }
213	      }
214	
215	      // ---- ram synlig/klickbar bara p 0.50-0.72 (--xfade1 * (1-xfade2)) ----
216	      var xfade1 = clamp01((p - 0.50) / 0.02);
217	      var xfade2 = clamp01((p - 0.70) / 0.02);
218	      var frameVisible = xfade1 > 0 && xfade2 < 1;
219	      revealFrame.style.visibility = (sigAct.live && frameVisible) ? 'visible' : 'hidden';
220	
221	      // ---- toppbar: mörk t.o.m. ramen, papper från utgångens mitt ----
222	      var dim = sigAct.live && p > 0.30 && p < 0.72;
223	      if (topbar) {
224	        topbar.classList.toggle('is-dim', !!dim);
225	        topbar.classList.toggle('zone-light', sigAct.live && p >= 0.86);
226	      }
227	      if (topbarLabel) {
228	        var vis = 0;
229	        if (p >= 0.54 && p <= 0.68) {
230	          var win = 0.68 - 0.54;
231	          var inEnd = 0.54 + win * 0.3, outStart = 0.68 - win * 0.3;
232	          if (p < inEnd) vis = smooth((p - 0.54) / (inEnd - 0.54));
233	          else if (p <= outStart) vis = 1;
234	          else vis = smooth(1 - (p - outStart) / (0.68 - outStart));
235	        }
236	        topbarLabel.style.opacity = sigAct.live ? vis.toFixed(3) : 0;
237	      }
238	    }
239	
240	    function loop() {
241	      applySignature();
242	      requestAnimationFrame(loop);
243	    }
244	    requestAnimationFrame(loop);
245	
246	    // ---- toppbarens zon för sektionerna EFTER signaturen (oförändrat) ----
247	    var zoneEls = document.querySelectorAll('[data-topbar-zone]');
248	    if ('IntersectionObserver' in window && zoneEls.length) {
249	      var zoneIO = new IntersectionObserver(function (entries) {
250	        entries.forEach(function (e) {
251	          if (e.isIntersecting) {
252	            var zone = e.target.getAttribute('data-topbar-zone');
253	            topbar.classList.toggle('zone-light', zone === 'light');
254	          }
255	        });
256	      }, { rootMargin: '-1px 0px -99% 0px', threshold: 0 });
257	      zoneEls.forEach(function (el) { zoneIO.observe(el); });
258	    }
259	
260	    // ---- ?preview= : force a formed state for screenshotting, no scroll ----
261	    var params = new URLSearchParams(location.search);
262	    var preview = params.get('preview');
263	    if (preview) {
264	      var targets = { window: 0.499, horai: 0.6, exit: 0.85, ledger: null };
265	      if (preview === 'ledger' && ledgerAct) {
266	        var yL = ledgerAct.top + ledgerAct.height * 0.85 - innerHeight * 0.4;
267	        scrollTo({ top: Math.max(0, yL), left: 0, behavior: 'instant' });
268	        api.read();
269	      } else if (Object.prototype.hasOwnProperty.call(targets, preview) && targets[preview] !== null) {
270	        var frac = targets[preview];
271	        var runPreview = function () {
272	          var y = sigAct.top + (sigAct.height - innerHeight) * frac;
273	          scrollTo({ top: Math.max(0, y), left: 0, behavior: 'instant' });
274	          api.read();
275	        };
276	        var waited = 0;
277	        (function waitForFrames() {
278	          if (seq.loaded >= seq.count || waited > 4000) { runPreview(); return; }
279	          waited += 60;
280	          setTimeout(waitForFrames, 60);
281	        })();
282	      }
283	    }
284	  }
285	
286	  fetch('assets/push/window-track.json')
287	    .then(function (r) { return r.json(); })
288	    .then(function (track) {
289	      if (reduce) renderStatic(track);
290	      else startMotion(track);
291	    })
292	    .catch(function () { /* geometry unavailable: base photo frames still read fine without the mask */ });
293	})();
