1	/* Alunix K1 Skymning — runda 3. Sex tokens + två typsnitt (scripts/scroll/NOTE.md).
2	   Aldrig restylad: .sc-stage, .sc-copy, .sc-scrim, [data-sc-*]. Allt annat härifrån. */
3	
4	:root {
5	  --sc-canvas:      #0b1424;
6	  --sc-surface:     #121c30;
7	  --sc-ink:         #f4efe6;
8	  --sc-ink-soft:    #b9c0d0;
