22	  /* Utgångens mål (runda 3): bevisradens Hōrai-plate, uppmätt med
23	     shots/measure-exit-target.py mot den byggda #proof-horai-media. Platen
24	     ligger inte i bild i den sista rutan av #exit:s eget pin-intervall (den
25	     kräver ytterligare scroll förbi ingressen och första uppslaget i #proof
26	     — mätt, inte gissat: se NOTES.md) — målet är därför platens naturliga
27	     viloläge, centrerat i viewporten, dit krympningen siktar. */
28	  --exit-tx: 74.5%;
29	  --exit-ty: 50.0%;
30	  --exit-sx: 0.321;
31	  --exit-sy: 0.386;
32	}
