34	html, body { overflow-x: clip; }
35	
36	/* ------------------------------------------------------------- toppbar -- */
37	.topbar {
38	  position: fixed; inset: 0 0 auto 0; z-index: 80;
39	  display: flex; align-items: center; justify-content: space-between;
40	  padding: clamp(1rem, 3vw, 1.75rem) clamp(1.25rem, 4vw, 2.5rem);
41	  pointer-events: none;
42	}
43	/* Two static gradient layers, cross-fading by opacity only: swapping the
44	   gradient stops themselves (as one layer previously did) is an instant snap
45	   no matter what transitions, since only opacity/transform truly interpolate. */
46	.topbar::before, .topbar::after {
47	  content: ""; position: absolute; inset: 0; height: 220%; z-index: -1;
48	  transition: opacity 300ms var(--sc-ease-out, ease);
49	}
50	.topbar::before {
51	  background: linear-gradient(180deg, rgba(6,10,18,0.68) 0%, rgba(6,10,18,0.2) 55%, transparent 82%);
