57	  opacity: 0;
58	}
59	.topbar.is-dim::after { opacity: 1; }
60	
61	/* Paper zone (akt 4-5, white ground): flip to ink-on-paper with a hairline,
62	   drop the dark scrim entirely. Toggled by script.js's section observer. */
63	.topbar.zone-light { background: color-mix(in oklab, var(--paper) 92%, transparent); border-bottom: 1px solid var(--hairline-on-white); }
64	.topbar.zone-light::before, .topbar.zone-light::after { opacity: 0 !important; }
65	.topbar.zone-light .topbar__contact { color: var(--ink-on-white); border-bottom-color: color-mix(in oklab, var(--ink-on-white) 40%, transparent); }
66	.topbar.zone-light .topbar__label { color: var(--ink-soft-on-white); }
