69	
70	.topbar__mark { pointer-events: auto; line-height: 0; position: relative; display: block; width: 112px; height: 22px; }
71	.topbar__mark-img { height: 20px; width: auto; filter: drop-shadow(0 1px 3px rgba(0,0,0,0.4)); position: absolute; inset: 0; transition: opacity 300ms var(--sc-ease-out, ease); }
72	.topbar__mark-img--black { opacity: 0; filter: none; }
73	.topbar__contact {
74	  pointer-events: auto;
75	  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
