96	/* ------------------------------------------------------- reservläge/motion toggle -- */
97	.motion-only { display: none; }
98	html.motion .motion-only { display: block; }
99	html.motion .rm-only { display: none; }
100	.rm-only { display: block; }
101	
102	/* ------------------------------------------------------ akt 1-4a signatur -- */
103	.sig-stage { background: var(--sc-canvas); overflow: clip; }
104	
105	/* Fas 1 (p 0-0.46): kameraresan, ritad själv på canvasen. Fas "fortsatt zoom"
106	   (p 0.46-0.50): hela lagret (foto + fönstermask) skalas tillsammans med en
107	   CSS-transform, ursprung satt av script.js till fönstrets mittpunkt vid sista
108	   rutan. Fas "bytet" (p 0.50-0.52): lagret tonar bort medan den riktiga ramen
109	   tonar in -- samma bro-tekniker (oskärpa vid korstoningen) som runda 3, nu
110	   smalare fönster (0,02 i stället för 0,35 av den gamla akten) per denna
111	   rundas exakta faströrelser. */
112	.sig-photo-layer {
113	  position: absolute; inset: 0;
114	  /* Bugg (runda 5): canvasen är svart (2d-kontext med alpha:false) tills
115	     script.js hunnit rita en riktig ruta -- vid p=0 direkt efter
116	     sidladdning, innan f001.webp laddat, visade heron rubriken mot svart.
117	     dusk.webp här bakom canvasen täcker exakt den luckan; en gång canvasen
118	     ritar något alls (opak {alpha:false}) döljer den bakgrunden helt, så
119	     det finns aldrig två bilder synliga samtidigt. */
120	  background-image: url("assets/dusk.webp");
121	  background-size: cover;
122	  background-position: center;
123	  --zoom2: clamp(0, (var(--sc-p, 0) - 0.46) / 0.04, 1);
124	  --xfade1: clamp(0, (var(--sc-p, 0) - 0.50) / 0.02, 1);
125	  transform-origin: var(--sig-window-x, 50%) var(--sig-window-y, 50%);
126	  transform: scale(calc(1 + var(--zoom2) * 0.282));
127	  opacity: calc(1 - var(--xfade1));
128	  filter: blur(calc(4 * var(--xfade1) * (1 - var(--xfade1)) * 6px));
129	}
130	.window-glow, .window-fill, .window-glass {
131	  position: absolute; left: 0; top: 0; width: 0; height: 0;
132	  opacity: 0; z-index: 2; pointer-events: none;
133	}
134	.window-glow {
135	  background: radial-gradient(closest-side, color-mix(in oklab, var(--sc-accent) 85%, white) 0%, color-mix(in oklab, var(--sc-accent) 40%, transparent) 60%, transparent 100%);
136	}
137	.window-fill { object-fit: cover; display: block; }
138	.window-glass { overflow: hidden; mix-blend-mode: multiply; }
139	.window-glass__canvas { width: 100%; height: 100%; display: block; }
140	.sig-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
141	
142	.hero-copy {
143	  filter: blur(calc(min(var(--sc-p, 0), 0.3) * 46.67px));
144	}
145	.hero-title {
146	  font-weight: 300; font-size: clamp(2.2rem, 3.4rem + 1.6vw, 5.5rem);
147	  line-height: 1.05; letter-spacing: -0.01em; color: var(--sc-ink);
148	  max-width: 16ch;
