150	.accent-u { text-decoration: underline; text-decoration-color: var(--sc-accent); text-decoration-thickness: 2px; text-underline-offset: 0.1em; }
151	/* scroll_verify.py flaggade denna som en cue som aldrig når full opacitet
152	   (peak 0.86) -- opaciteten var en smaksak (en "tystare" underrad), inte en
153	   avsiktlig cue-gräns, och håller inte isär de två. Dämpningen sker nu genom
154	   en egen ton i stället, så cuen faktiskt kan nå 1. */
155	.hero-sub { color: var(--sc-ink); margin-top: var(--sc-4); font-size: var(--sc-t-lg); }
