169	.reveal-frame-slot { position: absolute; inset: 0; z-index: 2; }
170	.reveal-frame-slot iframe {
171	  position: absolute; inset: 0; width: 100%; height: 100%; border: 0;
172	  --xfade1: clamp(0, (var(--sc-p, 0) - 0.50) / 0.02, 1);
173	  --xfade2: clamp(0, (var(--sc-p, 0) - 0.70) / 0.02, 1);
174	  opacity: calc(var(--xfade1) * (1 - var(--xfade2)));
