176	     0.70) -- emil-design-eng flaggade att bara utgången var bruad, vilket
177	     lät fotolagret (som redan bruar sin egen sida av samma inträde) möta en
178	     skarp ram och läsa som två objekt i stället för en enda upplösning. */
179	  filter: blur(calc(4 * var(--xfade1) * (1 - var(--xfade1)) * 6px + 4 * var(--xfade2) * (1 - var(--xfade2)) * 6px));
180	}
