182	/* -------------------------------------------------------------- akt 4a exit -- */
183	.exit-sweep { position: absolute; inset: 0; background: var(--paper); z-index: 4; }
184	.exit-frame-wrap {
185	  position: absolute; inset: 0; z-index: 3;
186	  --xfade2: clamp(0, (var(--sc-p, 0) - 0.70) / 0.02, 1);
187	  --exitp: clamp(0, (var(--sc-p, 0) - 0.72) / 0.28, 1);
188	  opacity: var(--xfade2);
189	  filter: blur(calc(4 * var(--xfade2) * (1 - var(--xfade2)) * 6px));
190	  transform-origin: var(--exit-tx) var(--exit-ty);
191	  /* Icke-uniform skala (sx/sy separat) mot den uppmätta rektangeln: bilden
192	     INUTI omslaget använder object-fit:cover, så den kompenserar löpande för
193	     omslagets skiftande proportioner under resan i stället för att sträckas. */
194	  transform: scale(calc(1 - var(--exitp) * (1 - var(--exit-sx))),
195	                    calc(1 - var(--exitp) * (1 - var(--exit-sy))));
196	}
197	.exit-frame { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
198	.exit-copy { position: absolute; z-index: 5; left: var(--sc-gutter); right: var(--sc-gutter); bottom: clamp(2.5rem, 12vh, 6rem); }
199	.exit-heading {
200	  max-width: 20ch; font-weight: 600; color: var(--ink-on-white);
201	  font-size: clamp(2rem, 1.4rem + 3.6vw, 4.5rem); line-height: 1.16;
202	}
