209	.exit-lede { font-family: var(--sc-font-text); font-size: var(--sc-t-lg); color: var(--ink-soft-on-white); margin-top: var(--sc-4); max-width: 40ch; }
210	.exit-heading--static, .exit-lede--static { position: static; color: var(--ink-on-white); max-width: 24ch; }
211	.exit-lede--static { color: var(--ink-soft-on-white); margin-top: var(--sc-3); }
