213	/* ---------------------------------------------------------- akt 4b bevisrad -- */
214	/* Bugg (runda 5): en pinnad akt (data-sc-act="pin"/"scrub") lämnar alltid
215	   exakt en viewport-hög "svans" i slutet av sin egen sektion -- utrymmet
216	   position:sticky kräver för att den fastnålade scenen ska kunna glida bort
217	   normalt (höjd - vh = den aktiva pin-sträckan, resten är svansen). Den
218	   svansen kommer FÖRE #proof oavsett vad #proof själv har för toppmarginal,
219	   och gav ett tomt vitt fält på mer än en skärmhöjd mellan den färdigrests
220	   rubriken och första bevisraden. Fixen drar upp #proof i det utrymmet med
221	   en negativ marginal (vitt möter vitt, samma --paper-ton på båda sidor, så
222	   det syns aldrig som en skarv) i stället för att försöka korta av själva
223	   pin-mekaniken, som är gemensam för alla pinnade akter på sidan. Uppmätt
224	   mot skärmbilder (shots/gap-*.png) tills luften höll sig under en halv
225	   skärmhöjd. */
226	.proof-section {
227	  background: var(--paper); position: relative; z-index: 1;
228	  margin-top: -62vh;
229	  padding-top: clamp(1.5rem, 3vw, 2.5rem);
230	  padding-bottom: var(--sc-section);
231	}
232	/* Bildsidan bär 7 kolumner, texten 5 (BRIEF § "Bygg raden"): bilden är den
233	   tyngre, redovisande sidan; texten är etiketten bredvid. */
234	.proof-row { display: grid; grid-template-columns: 7fr 5fr; gap: clamp(1.5rem, 4vw, var(--sc-8)); align-items: center; }
235	.proof-row + .proof-row { margin-top: clamp(3rem, 8vw, var(--sc-10)); }
236	.proof-row--reverse { grid-template-columns: 5fr 7fr; }
237	.proof-row__media { margin: 0; grid-row: 1; }
238	.proof-row--reverse .proof-row__media { grid-column: 2; }
239	.proof-row__media img { width: 100%; display: block; aspect-ratio: 4/3; object-fit: cover; }
240	.proof-row__media--left, .proof-row__media--right { margin-top: 0; }
241	.proof-row:not(.proof-row--reverse) .proof-row__text { margin-top: clamp(1.5rem, 6vh, 6rem); }
242	.proof-row--reverse .proof-row__media { margin-top: clamp(1.5rem, 6vh, 6rem); }
243	.proof-row__num { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-accent-ink); background: color-mix(in oklab, var(--sc-accent) 70%, transparent); display: inline-block; padding: 0.15em 0.55em; letter-spacing: var(--sc-track-wide); margin: 0 0 var(--sc-3); }
244	.proof-row__title { font-weight: 500; font-size: var(--sc-t-3xl); color: var(--ink-on-white); margin: 0; }
245	.proof-row__body { color: var(--ink-soft-on-white); font-size: var(--sc-t-base); margin-top: var(--sc-3); max-width: 36ch; }
246	.proof-row__site { font-family: var(--sc-font-text); font-size: var(--sc-t-xs); letter-spacing: var(--sc-track-wide); text-transform: uppercase; color: var(--ink-soft-on-white); margin-top: var(--sc-4); }
247	
248	/* ------------------------------------------------------------ akt 5 liggare -- */
249	.ledger-section { background: var(--paper); padding-block: var(--sc-section); }
250	.ledger-heading { color: var(--ink-on-white); font-weight: 300; font-size: clamp(2rem, 1.5rem + 3vw, 4rem); margin: 0 0 var(--sc-8); }
251	.ledger-list { border-top: 1px solid var(--hairline-on-white); }
252	.ledger-row {
253	  position: relative; display: grid; grid-template-columns: 1fr auto; align-items: baseline;
254	  gap: var(--sc-4); padding-block: clamp(1.5rem, 4vw, var(--sc-7));
255	  border-bottom: 1px solid var(--hairline-on-white);
256	}
257	.ledger-row__hairline {
258	  position: absolute; left: 0; right: 0; bottom: -1px; height: 1px; margin: 0;
259	  background: var(--ink-on-white); transform-origin: left center;
260	  /* Ritas i takt med scrollen: --sc-p publiceras på #ledger (flow-akt),
261	     varje rad har sitt eget fönster via en index-offset (--row-i). */
262	  transform: scaleX(clamp(0, (var(--sc-p, 0) - 0.15 - var(--row-i, 0) * 0.18) / 0.22, 1));
263	}
264	.ledger-row__desc { color: var(--ink-soft-on-white); font-size: var(--sc-t-base); max-width: 46ch; margin: 0; }
265	.ledger-row__price { font-family: var(--sc-font-display); font-weight: 500; font-size: clamp(1.5rem, 1.1rem + 2vw, 3rem); color: var(--ink-on-white); text-align: right; white-space: nowrap; margin: 0; font-variant-numeric: tabular-nums; }
266	.ledger-list--static .ledger-row__hairline--static { transform: scaleX(1); }
267	
268	/* --------------------------------------------------------------- akt 6 landning -- */
269	.landing-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; display: flex; align-items: flex-end; background: var(--sc-canvas); }
270	.landing-night { position: absolute; inset: 0; z-index: 0; clip-path: inset(calc(50% - min(var(--sc-p, 0), 1) * 50%) 0 calc(50% - min(var(--sc-p, 0), 1) * 50%) 0); }
271	.landing-night__img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
272	/* scroll_verify.py mätte kontakt@alunix.se ner mot 1.53:1 (golv 3.0) mot
273	   nattfotots ljusa partier (upplysta fasader, torn). En skrim bara där
274	   texten sitter, aldrig hela bilden. */
275	.landing-scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(5,8,14,0.92) 0%, rgba(5,8,14,0.55) 45%, transparent 78%); }
276	.landing-copy { position: relative; z-index: 2; padding-bottom: clamp(2.5rem, 8vh, 5rem); width: 100%; }
277	.landing-mailto { font-family: var(--sc-font-display); font-weight: 300; font-size: clamp(2rem, 1.3rem + 4vw, 5rem); color: var(--sc-ink); text-decoration: none; border-bottom: 2px solid color-mix(in oklab, var(--sc-ink) 40%, transparent); }
278	.landing-mailto:hover { border-bottom-color: var(--sc-accent); color: var(--sc-accent); transition: color 200ms ease, border-color 200ms ease; }
279	.landing-address { font-size: var(--sc-t-lg); color: var(--sc-ink-soft); margin-top: var(--sc-5); max-width: 42ch; }
280	.landing-credits { font-family: var(--sc-font-text); font-size: var(--sc-t-xs); color: var(--sc-ink-soft); margin-top: var(--sc-8); }
281	.landing-copy--static { padding: clamp(1.5rem,5vw,3rem); position: static; }
282	
283	/* ---------------------------------------------------------- reservläge -- */
284	.rm-only { background: var(--sc-canvas); }
285	.rm-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; }
286	.rm-section--hero { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(1.5rem,5vw,3rem); }
287	.rm-section__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
288	.rm-section__scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(6,10,18,0.85) 0%, rgba(6,10,18,0.35) 45%, transparent 70%); }
289	.rm-hero-copy { position: relative; z-index: 2; max-width: 40rem; }
290	.rm-section--window { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-5); background: #05070c; }
291	.rm-window-stage { position: relative; width: min(92vw, 1200px); aspect-ratio: 3 / 2; overflow: clip; border-radius: 2px; }
292	.rm-window-stage__photo, .rm-window-mask__fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
293	.rm-window-mask { position: absolute; z-index: 2; overflow: hidden; }
294	.rm-window-mask__glass { position: absolute; inset: 0; mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.22), rgba(20,14,8,0.3)); }
295	.rm-section--frame { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-4); background: #05070c; }
296	.rm-frame-slot { width: min(94vw, 1400px); aspect-ratio: 16 / 9; border: 1px solid color-mix(in oklab, var(--sc-ink) 16%, transparent); }
297	.rm-frame-slot iframe { width: 100%; height: 100%; border: 0; display: block; }
298	.rm-caption { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-ink-soft); text-align: center; margin: 0; }
299	.rm-section--proof { background: var(--paper); display: flex; flex-direction: column; justify-content: center; padding: clamp(1.5rem,6vw,4rem); gap: var(--sc-7); }
300	.rm-proof-rows { display: flex; flex-direction: column; gap: var(--sc-8); }
301	.rm-proof-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sc-6); align-items: center; }
302	.rm-proof-row img { width: 100%; aspect-ratio: 4/3; object-fit: cover; display: block; }
303	.rm-section--ledger { background: var(--paper); display: flex; flex-direction: column; justify-content: center; padding: clamp(1.5rem,6vw,4rem); }
304	.rm-section--landing { display: flex; align-items: flex-end; }
305	
306	@media (max-width: 860px) {
307	  .hero-title { max-width: 14ch; }
308	  .exit-heading, .exit-heading--static { max-width: none; }
309	  .proof-row, .proof-row--reverse { grid-template-columns: 1fr; }
310	  .proof-row--reverse .proof-row__media { grid-column: 1; }
311	  .proof-row:not(.proof-row--reverse) .proof-row__text,
312	  .proof-row--reverse .proof-row__media { margin-top: var(--sc-5); }
313	  .rm-proof-row { grid-template-columns: 1fr; }
314	  .ledger-row { grid-template-columns: 1fr; }
315	  .ledger-row__price { text-align: left; }
316	}
