function warpStreet(t) {
  var bx = [0, 0.374, 0.5192, 1];
  var by = [0, 0.374, 0.616, 1];
  for (var i = 0; i < bx.length - 1; i++) {
    if (t <= bx[i + 1] || i === bx.length - 2) {
