    var c = coverBox(boxW, boxH, NATURAL_W, NATURAL_H);
    var px = c.offX + kf.x * NATURAL_W * c.scale;
    var py = c.offY + kf.y * NATURAL_H * c.scale;
    var pw = kf.w * NATURAL_W * c.scale;
    var ph = kf.h * NATURAL_H * c.scale;
